package com.example.banking.security;
import com.example.banking.entity.AppUser; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.Date; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService {
 private final SecretKey key; private final long ttl;
 public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.ttl-seconds:900}") long ttl){if(secret.getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalArgumentException("app.jwt.secret must contain at least 32 bytes");if(ttl<60)throw new IllegalArgumentException("JWT lifetime must be at least 60 seconds");this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.ttl=ttl;}
 public String create(AppUser user){Instant now=Instant.now();return Jwts.builder().id(java.util.UUID.randomUUID().toString()).subject(user.getEmail()).claim("uid",user.getId()).claim("roles",user.getRoles().stream().map(Enum::name).toList()).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(ttl))).signWith(key).compact();}
 public String subject(String token){return claims(token).getSubject();} public String tokenId(String token){return claims(token).getId();} public Instant expiresAt(String token){return claims(token).getExpiration().toInstant();} private Claims claims(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} public long ttl(){return ttl;}
}
